const RM=matchMedia('(prefers-reduced-motion: reduce)').matches;
(()=>{const t=document.getElementById('toast');let h;const show=m=>{if(!t)return;t.textContent=m;t.classList.remove('show');void t.offsetWidth;t.classList.add('show');clearTimeout(h);h=setTimeout(()=>t.classList.remove('show'),2000)};
document.querySelectorAll('[data-copy]').forEach(b=>b.addEventListener('click',()=>{const s=b.dataset.copy,m=b.dataset.msg||'已复制';const fb=()=>{const a=document.createElement('textarea');a.value=s;a.setAttribute('readonly','');a.style.cssText='position:fixed;opacity:0';document.body.appendChild(a);a.select();let ok=false;try{ok=document.execCommand('copy')}catch(e){}a.remove();show(ok?m:'请手动复制：'+s)};if(navigator.clipboard&&window.isSecureContext)navigator.clipboard.writeText(s).then(()=>show(m),fb);else fb()}));
const mb=document.querySelector('[data-menu]');if(mb){const hd=mb.closest('header'),nav=document.getElementById(mb.getAttribute('aria-controls'));const set=o=>{hd.classList.toggle('open',o);mb.setAttribute('aria-expanded',o);document.documentElement.classList.toggle('menu-open',o)};mb.addEventListener('click',()=>set(mb.getAttribute('aria-expanded')!=='true'));nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>set(false)));addEventListener('keydown',ev=>{if(ev.key==='Escape'&&hd.classList.contains('open')){set(false);mb.focus()}});matchMedia('(min-width:861px)').addEventListener('change',q=>{if(q.matches)set(false)})}
const els=document.querySelectorAll('[data-rv]');if(RM||!('IntersectionObserver' in window)){els.forEach(x=>x.classList.add('in'));}else{document.documentElement.classList.add('rv-on');const io=new IntersectionObserver(es=>es.forEach(x=>{if(x.isIntersecting){x.target.classList.add('in');io.unobserve(x.target)}}),{rootMargin:'0px 0px -10% 0px'});els.forEach(x=>io.observe(x))}})();
